const Table& c99_table() {
  static const Table table{
      .terminal_count = 112,
      .symbols = kSymbols,
      .row_start = kRowStart,
      .entry_symbol = kEntrySymbol,
      .entry_action = kEntryAction,
      .rule_origin = kRuleOrigin,
      .rule_start = kRuleStart,
      .rule_expansion = kRuleExpansion,
      .rule_alias = kRuleAlias,
      .starts = kStarts,
      .lex_terminals = kLexTerminals,
      .keywords = kKeywords,
      .allowed = kAllowed,
  };
  return table;
}

